{
  "ruleset_id": "programma_dopolnitelnogo_obrazovaniya",
  "rules": [
    {
      "description": "Организация должна предоставить действующую лицензию на образовательную деятельность.",
      "severity": "critical",
      "category": "license",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Объём программы должен составлять не менее 72 часов.",
      "severity": "critical",
      "category": "curriculum_hours",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Не менее 80% преподавателей должны иметь профильную квалификацию.",
      "severity": "critical",
      "category": "teacher_qualification",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Формат реализации программы должен быть только «очно» или «смешанно».",
      "severity": "critical",
      "category": "delivery_format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grantovaya-programma-2026-v2026-1",
  "rules": [
    {
      "description": "На дату подачи организация-заявитель должна быть зарегистрирована не менее 12 месяцев.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "application_form.months_registered",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Запрашиваемая сумма не должна превышать 100 000 евро.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "le",
        "value": 100000
      }
    },
    {
      "description": "Доля расходов на оборудование не должна превышать 40% общего бюджета.",
      "severity": "major",
      "category": "equipment_share",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "le",
        "value": 40
      }
    },
    {
      "description": "Пакет документов должен включать форму заявки.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Пакет документов должен включать детализированный бюджет.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Пакет документов должен включать свидетельство о регистрации или выписку из реестра.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Пакет документов должен включать последнюю финансовую отчётность.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 октября 2026 года включительно.",
      "severity": "major",
      "category": "deadline",
      "condition": {
        "field": "application_form.submission_date",
        "op": "le",
        "value": "2026-10-01"
      }
    },
    {
      "description": "Форма заявки должна быть подписана законным представителем.",
      "severity": "critical",
      "category": "signature",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Запрашиваемая в форме сумма должна точно совпадать с итогом детализированного бюджета.",
      "severity": "major",
      "category": "amount_consistency",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "consistent",
        "value": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ]
      }
    },
    {
      "description": "Финансовая отчётность должна охватывать FY2025.",
      "severity": "minor",
      "category": "reporting_period",
      "condition": {
        "field": "finance_statement.period",
        "op": "eq",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "programma-kapitalnogo-remonta",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "building_eligibility",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должно быть поддержано не менее чем 66% голосов.",
      "severity": "critical",
      "category": "owner_approval",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен быть приложен акт обследования дефектов.",
      "severity": "major",
      "category": "required_document",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 апреля 2027 года.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-meditsinskikh-izdeliy",
  "rules": [
    {
      "description": "Для товара обязательно наличие регистрационного удостоверения.",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "documents.medical_registration.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "На дату поставки остаточный срок годности должен составлять не менее 12 месяцев.",
      "severity": "critical",
      "category": "expiry",
      "condition": {
        "field": "product.expiry_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Для изделий, требующих холодовой цепи, обязателен протокол её соблюдения.",
      "severity": "critical",
      "category": "cold_chain",
      "condition": {
        "field": "documents.cold_chain_protocol.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Страной происхождения товара должна быть Россия или государство ЕАЭС.",
      "severity": "critical",
      "category": "origin",
      "condition": {
        "field": "product.origin_country",
        "op": "in",
        "value": [
          "Россия",
          "государство ЕАЭС"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnyh-rabot",
  "rules": [
    {
      "description": "Годовая выручка поставщика должна составлять не менее 10 000 000 рублей.",
      "severity": "critical",
      "category": "turnover",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "Для допуска требуется действующее свидетельство СРО.",
      "severity": "critical",
      "category": "sro_certificate",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Участник допускается только со статусом санкционной проверки «clear».",
      "severity": "critical",
      "category": "sanctions",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 20 ноября 2026 года.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "konkurs-prikladnykh-issledovaniy",
  "rules": [
    {
      "description": "Руководитель должен иметь степень «кандидат наук» или «доктор наук».",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": [
          "кандидат наук",
          "доктор наук"
        ]
      }
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах.",
      "severity": "critical",
      "category": "publications",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Согласие на размещение обезличенных данных исследования должно быть представлено.",
      "severity": "critical",
      "category": "open_data_consent",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Бюджет, заявленный в форме, должен совпадать с итогом сметы.",
      "severity": "major",
      "category": "budget_consistency",
      "condition": {
        "field": "application.declared_budget_rub",
        "op": "consistent",
        "value": [
          "budget.total_rub"
        ]
      }
    }
  ]
}
